function favoritesFor(orders,products,name){const key=person(name),stats=new Map();for(const o of orders){if(o.status==='cancelled')continue;let items;try{items=JSON.parse(o.items)}catch{continue}if(!Array.isArray(items))continue;for(const i of items){if(!i||person(i.recipient)!==key)continue;const prod=products.find(p=>p.id===i.id);if(!prod)continue;const q=Number.isInteger(i.qty)&&i.qty>0?i.qty:1;let st=stats.get(prod.id);if(!st){st={productId:prod.id,name:prod.name,count:0,sugarCounts:new Map(),sugar:0,milk:'normal',last:''};stats.set(prod.id,st)}st.count+=q;const sugars=Array.isArray(i.sugars)&&i.sugars.length?i.sugars:Array(q).fill(i.sugar);for(const raw of sugars){const sg=Number.isInteger(raw)&&raw>=0?raw:0,c=st.sugarCounts.get(sg)||{n:0,last:''};c.n+=1;if(o.created>=c.last)c.last=o.created;st.sugarCounts.set(sg,c)}if(o.created>=st.last){st.last=o.created;st.milk=i.milk==='lactose_free'&&prod.milk?'lactose_free':'normal'}}}return [...stats.values()].map(st=>{let best=null;for(const [sg,c] of st.sugarCounts)if(!best||c.n>best.n||(c.n===best.n&&c.last>best.last))best={sg,...c};return {productId:st.productId,name:st.name,count:st.count,sugar:best?best.sg:0,milk:st.milk,last:st.last}}).sort((a,b)=>b.count-a.count||b.last.localeCompare(a.last)).slice(0,3).map(({last,...f})=>f)}
async function findPerson(db,id){return await db.prepare('SELECT id,name FROM staff WHERE id=? UNION ALL SELECT id,name FROM customer_profiles WHERE id=?').bind(id,id).first()}
function computeBalances(orders,payments){const m=new Map(),get=k=>{let x=m.get(k);if(!x){x={person:k,total:0,count:0,paid:0};m.set(k,x)}return x};for(const o of orders){if(o.status==='pending'||o.status==='cancelled')continue;let items=o.items;if(typeof items==='string'){try{items=JSON.parse(items)}catch{continue}}if(!Array.isArray(items))continue;for(const i of items){if(!i||typeof i!=='object')continue;const x=get(person(i.payer));x.total+=(Number(i.price)||0)*(Number(i.qty)||0);x.count+=Number(i.qty)||0}}for(const p of payments)get(person(p.person)).paid+=Number(p.amount)||0;return [...m.values()].map(x=>({...x,remaining:x.total-x.paid})).sort((a,b)=>a.person.localeCompare(b.person,'tr'))}
async function allBalances(db){const orders=(await db.prepare('SELECT status,items FROM orders').all()).results,payments=(await db.prepare('SELECT person,amount FROM payments').all()).results;return computeBalances(orders,payments)}
const changesOf=r=>Number(r?.meta?.changes??r?.changes??0);
