function cartItems(settings,list){if(!Array.isArray(list)||!list.length||list.length>40)return null;return list.flatMap(i=>{const prod=settings.products.find(p=>p.id===i.id);if(!prod||!clean(i.recipient)||!clean(i.payer)||!Number.isInteger(i.qty)||i.qty<1||i.qty>20)throw Error('Kahve bilgilerini kontrol edin.');const milk=i.milk===undefined||i.milk==='normal'?'normal':i.milk==='lactose_free'?'lactose_free':null;if(!milk)throw Error('Kahve bilgilerini kontrol edin.');if(milk==='lactose_free'&&!prod.milk)throw Error(NO_LACTOSE);const base={id:prod.id,name:prod.name,price:prod.price+(milk==='lactose_free'?settings.lactoseFreeExtra:0),milk,recipient:clean(i.recipient,80),payer:person(i.payer)};if(i.sugars!==undefined){if(!Array.isArray(i.sugars)||i.sugars.length!==i.qty||i.sugars.some(s=>!Number.isInteger(s)||s<0||s>99))throw Error('Kahve bilgilerini kontrol edin.');return i.sugars.map(sugar=>({...base,qty:1,sugar}))}if(!Number.isInteger(i.sugar)||i.sugar<0||i.sugar>99)throw Error('Kahve bilgilerini kontrol edin.');return [{...base,qty:i.qty,sugar:i.sugar}]})}
