const fold=v=>person(v).replace(/ı/g,'i'),PREF_MILK=['normal','lactose_free'];
function mergeManual(favs,products,pref){if(!pref)return favs;const prod=pref.coffee?products.find(p=>p.id===pref.coffee||fold(p.name)===fold(pref.coffee)):null;let out=favs.map(f=>({...f}));if(prod){if(out.some(f=>f.productId===prod.id))out.sort((a,b)=>(b.productId===prod.id)-(a.productId===prod.id));else out.unshift({productId:prod.id,name:prod.name,count:0,sugar:0,milk:'normal'})}for(const f of out){if(Number.isInteger(pref.sugar))f.sugar=pref.sugar;if(pref.milk)f.milk=pref.milk}return out.slice(0,3)}
export async function buildBackup(db){const row=await db.prepare('SELECT data FROM settings WHERE id=1').first();const out={version:1,exportedAt:new Date().toISOString(),settings:row?JSON.parse(row.data):null};for(const t of BACKUP_TABLES){const rows=(await db.prepare('SELECT * FROM '+t).all()).results.map(r=>({...r}));out[t]=t==='orders'?rows.map(o=>{let items=[];try{items=JSON.parse(o.items)}catch{}return {...o,items}}):rows}return out}
async function restoreBackup(db,b){if(!isObj(b)||b.version!==1)return {status:400,body:{error:'Yedek dosyası tanınmadı (version 1 bekleniyor).'}};if(b.settings!==null&&b.settings!==undefined&&!(isObj(b.settings)&&Array.isArray(b.settings.products)))return {status:400,body:{error:'Yedekteki ayarlar geçersiz.'}};
for(const t of BACKUP_TABLES){const rows=b[t]===undefined?[]:b[t];if(!Array.isArray(rows)||rows.length>200000)return {status:400,body:{error:'Yedekte "'+t+'" listesi geçersiz.'}};for(let n=0;n<rows.length;n++)if(!isObj(rows[n])||!RESTORE_SPEC[t].check(rows[n]))return {status:400,body:{error:'Yedekte "'+t+'" kaydı geçersiz (sıra '+(n+1)+').'}}}
const row=await db.prepare('SELECT data FROM settings WHERE id=1').first();const result={};if(isObj(b.settings)){const n=row?0:await runStatements(db,[db.prepare('INSERT OR IGNORE INTO settings(id,data) VALUES(1,?)').bind(JSON.stringify(b.settings))]);result.settings={added:n,skipped:1-n}}else result.settings={added:0,skipped:0};
for(const t of BACKUP_TABLES){const rows=b[t]||[],spec=RESTORE_SPEC[t],added=await runStatements(db,rows.map(r=>db.prepare(spec.sql).bind(...spec.args(r))));result[t]={added,skipped:rows.length-added}}return {status:200,body:{ok:true,result}}}
const stockRow=r=>({id:r.id,name:r.name,unit:r.unit,qty:Number(r.qty),min_qty:Number(r.min_qty),updated:r.updated});
