function recipeNeeds(settings,items){const need=new Map();for(const i of items||[]){const prod=settings.products.find(p=>p.id===i.id);if(!prod||!prod.recipe)continue;const q=Number(i.qty)||1;for(const r of prod.recipe){const id=i.milk==='lactose_free'&&r.lactoseFreeItemId?r.lactoseFreeItemId:r.itemId;need.set(id,(need.get(id)||0)+r.amount*q)}}return need}
const PAID_ST=['confirmed','preparing','delivered'];
const isUnique=e=>String(e&&e.message).includes('UNIQUE')||(e&&e.code)==='23505';
// Sipariş borca girince reçeteye göre stok düşer, iptalde geri eklenir. Hareketler (ref=sipariş) üzerinden net toplam kontrol edilir: iki kez düşmez.
async function syncOrderStock(db,settings,orderId,items,oldStatus,newStatus){
if(!PAID_ST.includes(newStatus)&&newStatus!=='cancelled')return;
const moves=(await db.prepare("SELECT item_id,delta,reason FROM stock_moves WHERE ref=? AND reason IN ('order','cancel')").bind(orderId).all()).results,net=new Map();let cancels=0;for(const m of moves){net.set(m.item_id,(net.get(m.item_id)||0)+Number(m.delta));if(m.reason==='cancel')cancels++}
const deducted=[...net.values()].some(v=>v<-1e-9),now=new Date().toISOString(),stmts=[],existing=new Set((await stockItems(db)).map(x=>x.id));
const add=(reason,id,delta)=>{stmts.push(db.prepare('INSERT INTO stock_moves(id,item_id,delta,reason,ref,created) VALUES(?,?,?,?,?,?)').bind(reason[0]+':'+orderId+':'+id+':'+cancels,id,delta,reason,orderId,now));stmts.push(db.prepare('UPDATE stock_items SET qty=qty+?,updated=? WHERE id=?').bind(delta,now,id))};
if(PAID_ST.includes(newStatus)&&!PAID_ST.includes(oldStatus)&&!deducted){for(const [id,amt] of recipeNeeds(settings,items))if(existing.has(id)&&amt>0)add('order',id,-rnd(amt))}
else if(newStatus==='cancelled'&&deducted){for(const [id,v] of net)if(v<-1e-9&&existing.has(id))add('cancel',id,rnd(-v))}
if(!stmts.length)return;try{await runStatements(db,stmts)}catch(e){if(!isUnique(e))throw e}}
