const FX_TTL=30*60e3,TCMB_URL='https://www.tcmb.gov.tr/kurlar/today.xml',ER_URL='https://open.er-api.com/v6/latest/USD';let FX_MEM=null;
export const _resetFx=()=>{FX_MEM=null};
export function parseTcmbUsd(xml){const m=/<Currency\b[^>]*CurrencyCode="USD"[^>]*>([\s\S]*?)<\/Currency>/.exec(String(xml||''));if(!m)return null;const f=/<ForexSelling>\s*([\d.,]+)\s*<\/ForexSelling>/.exec(m[1]);const v=f?parseFloat(f[1].replace(',','.')):NaN;return isFinite(v)&&v>1&&v<100000?v:null}
async function fxGet(f,url){const ac=new AbortController(),t=setTimeout(()=>ac.abort(),4000);try{const r=await f(url,{signal:ac.signal,headers:{'User-Agent':'coffyman'}});if(!r.ok)throw Error('http '+r.status);return await r.text()}finally{clearTimeout(t)}}
async function getFx(env,force){const now=Date.now();if(!force&&FX_MEM&&!FX_MEM.stale&&now-FX_MEM.at<FX_TTL)return {usdTry:FX_MEM.usdTry,source:FX_MEM.source,fetchedAt:FX_MEM.fetchedAt,stale:false};
const f=env.FETCH||fetch;let got=null;
try{const v=parseTcmbUsd(await fxGet(f,TCMB_URL));if(v)got={usdTry:v,source:'TCMB'}}catch{}
if(!got){try{const v=Number(JSON.parse(await fxGet(f,ER_URL))?.rates?.TRY);if(isFinite(v)&&v>1&&v<100000)got={usdTry:v,source:'open.er-api.com'}}catch{}}
if(got){FX_MEM={...got,fetchedAt:new Date(now).toISOString(),at:now,stale:false};try{if(env.BACKUPS)await env.BACKUPS.set('fx/latest.json',{usdTry:got.usdTry,source:got.source,fetchedAt:FX_MEM.fetchedAt})}catch{}return {usdTry:got.usdTry,source:got.source,fetchedAt:FX_MEM.fetchedAt,stale:false}}
let last=FX_MEM;if(!last&&env.BACKUPS){try{const b=await env.BACKUPS.get('fx/latest.json');if(b&&Number(b.usdTry)>0&&typeof b.fetchedAt==='string')last={usdTry:Number(b.usdTry),source:String(b.source||''),fetchedAt:b.fetchedAt,at:0}}catch{}}
if(last){FX_MEM={...last,stale:true};return {usdTry:last.usdTry,source:last.source,fetchedAt:last.fetchedAt,stale:true}}
return {usdTry:null,source:null,fetchedAt:null,stale:false}}
